(()=>{const host=document.getElementById('L01-lab');if(!host)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e;const defaults={count:308,squares:4,dilution:2};let values={...defaults},result={};const inputs={};for(const k of Object.keys(defaults)){inputs[k]=host.querySelector('#L01-'+k);inputs[k].addEventListener('input',()=>set({[k]:Number(inputs[k].value)}));}
function set(p){for(const k of Object.keys(defaults))if(k in p)values[k]=Math.max(Number(inputs[k].min),Math.min(Number(inputs[k].max),Number(p[k])));draw();return result;}
function draw(){for(const k in inputs){inputs[k].value=values[k];host.querySelector('[data-value="'+k+'"]').textContent=String(values[k]);}const n=values.count,c=n*values.dilution/(values.squares*.0001),sd=1/Math.sqrt(n);result={...values,concentration:c,relativeSD:sd,stockVolumeUl:10000/c*1000};const svg=host.querySelector('svg');const x=n=>70+560*Math.log(n/25)/Math.log(3200/25),y=cv=>280-cv*1100;let d='';for(let n=25;n<=3200;n+=5)d+=(d?'L':'M')+x(n).toFixed(2)+','+y(1/Math.sqrt(n)).toFixed(2);let ticks='';for(const n of [25,100,400,1600,3200])ticks+=`<text x="${x(n)}" y="305" text-anchor="middle">${n}</text>`;for(const p of [0,5,10,15,20])ticks+=`<line x1="70" y1="${y(p/100)}" x2="630" y2="${y(p/100)}" stroke="#dbe3e6"/><text x="60" y="${y(p/100)+5}" text-anchor="end">${p}%</text>`;svg.innerHTML=`<rect width="700" height="360" fill="#faf9f5"/><g font-size="14" fill="#263e48">${ticks}<path d="${d}" fill="none" stroke="#186e83" stroke-width="3"/><circle cx="${x(n)}" cy="${y(sd)}" r="7" fill="#cd803f"/><text x="350" y="345" text-anchor="middle">${tr('累计细胞计数（对数轴）','Accumulated cell count (log scale)')}</text><text x="350" y="25" text-anchor="middle">${tr('理想相对抽样标准差','Ideal relative sampling standard deviation')}</text></g>`;host.querySelector('[data-result]').textContent=tr(`原液浓度 ${c.toLocaleString('zh-CN',{maximumFractionDigits:0})} 个/mL；理想相对标准差 ${(100*sd).toFixed(2)}%；取一万个细胞需原液 ${result.stockVolumeUl.toFixed(2)} μL。`,`Stock concentration ${c.toLocaleString('en-US',{maximumFractionDigits:0})} cells/mL; ideal relative SD ${(100*sd).toFixed(2)}%; stock volume for 10,000 cells ${result.stockVolumeUl.toFixed(2)} μL.`);}
host.querySelector('#L01-more').addEventListener('click',()=>{const factor=Math.min(2,16/values.squares,3200/values.count);set({count:values.count*factor,squares:values.squares*factor});});host.querySelector('#L01-reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...result}),reset:()=>set(defaults)};draw();})();
